do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P061', 'P068', 'P074', 'P078', 'P232', 'P233', 'P234', 'P235', 'P236', 'P237', 'P238', 'P239', 'P240', 'P241', 'P242', 'P243', 'P244', 'P245', 'P246', 'P247', 'P248', 'P249', 'P250', 'P251', 'P252')) <> 25 then
